window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3eaf825f241c5298"]={"versions": [{"id": "FIG-3eaf825f241c5298", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dateiorganisationsdiagramm (Include-Hierarchie / Komponentenabhängigkeitsdiagramm) der AUTOSAR Classic Platform RTE. Dargestellt ist die beispielhafte Inklusionsbeziehung zwischen dem generierten RTE-Quellcode (<code>Rte.c</code>), den zugehörigen generierten Header-Dateien sowie den standardisierten Schnittstellen-Headern der RTE-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dateien und Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code>: Generiertes C-Implementierungsmodul des RTE („Generated RTE“, grau).\n</li><li><code>Application Header File</code>: Generierte komponenten-spezifische Header-Dateien (grau, gestapelt dargestellt, Kardinalität <code>*</code>).\n</li><li><code>Rte_Type.h</code>: Generierter Typdefinitions-Header der RTE (grau).\n</li><li><code>Rte_Main.h</code>: Generierter Header für Lifecycle- und Scheduling-Funktionen (grau).\n</li><li><code>Rte_Hook.h</code>: Generierter Header für RTE-Hook-Routinen (grau).\n</li><li><code>Rte.h</code>: Standardisierter RTE-Basis-Header (weiß / „Standardized“).\n</li><li><code>Rte_Cfg.h</code>: Standardisierter Konfigurations-Header (weiß / „Standardized“).\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code> inkludiert <code>Rte_Hook.h</code> (Multiplizität <code>1</code>), <code>Application Header File</code> (Multiplizität <code>*</code>), <code>Rte_Type.h</code> (Multiplizität <code>1</code>) und <code>Rte_Main.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Hook.h</code> inkludiert <code>Rte_Cfg.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Application Header File</code> inkludiert <code>Rte_Type.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Type.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Main.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Include- und Kompilierzeit-Ablauf: Der C-Präprozessor löst beim Übersetzen von <code>Rte.c</code> die Abhängigkeiten über die Pfeilrichtungen auf. <code>Rte.c</code> bindet die anwendungsspezifischen Header sowie RTE-interne Header ein. Indirekt wird über <code>Rte_Type.h</code> und <code>Rte_Main.h</code> stets die übergeordnete standardisierte Schnittstellendefinition <code>Rte.h</code> referenziert, während Konfigurationsparameter aus <code>Rte_Cfg.h</code> über <code>Rte_Hook.h</code> bereitgestellt werden. Es findet kein dynamischer Laufzeit-Nachrichtenaustausch statt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt beispielhaften Charakter („Example of header file use by the generated RTE“) für Codegeneratoren und Integratoren. Die genaue Struktur der Inklusionen in <code>Rte.c</code> ist ein Implementierungsdetail des RTE-Generators. Wesentlich ist die Trennung zwischen generierten Artefakten („Generated“, grau) und standardisierten Header-Dateien („Standardized“, weiß), um zirkuläre Abhängigkeiten zu vermeiden und konsistente Typdefinitionen sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-719a7e57d62637c1", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dateiorganisationsdiagramm (Include-Hierarchie / Komponentenabhängigkeitsdiagramm) der AUTOSAR Classic Platform RTE. Dargestellt ist die beispielhafte Inklusionsbeziehung zwischen dem generierten RTE-Quellcode (<code>Rte.c</code>), den zugehörigen generierten Header-Dateien sowie den standardisierten Schnittstellen-Headern der RTE-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dateien und Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code>: Generiertes C-Implementierungsmodul des RTE („Generated RTE“, grau).\n</li><li><code>Application Header File</code>: Generierte komponenten-spezifische Header-Dateien (grau, gestapelt dargestellt, Kardinalität <code>*</code>).\n</li><li><code>Rte_Type.h</code>: Generierter Typdefinitions-Header der RTE (grau).\n</li><li><code>Rte_Main.h</code>: Generierter Header für Lifecycle- und Scheduling-Funktionen (grau).\n</li><li><code>Rte_Hook.h</code>: Generierter Header für RTE-Hook-Routinen (grau).\n</li><li><code>Rte.h</code>: Standardisierter RTE-Basis-Header (weiß / „Standardized“).\n</li><li><code>Rte_Cfg.h</code>: Standardisierter Konfigurations-Header (weiß / „Standardized“).\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code> inkludiert <code>Rte_Hook.h</code> (Multiplizität <code>1</code>), <code>Application Header File</code> (Multiplizität <code>*</code>), <code>Rte_Type.h</code> (Multiplizität <code>1</code>) und <code>Rte_Main.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Hook.h</code> inkludiert <code>Rte_Cfg.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Application Header File</code> inkludiert <code>Rte_Type.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Type.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Main.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Include- und Kompilierzeit-Ablauf: Der C-Präprozessor löst beim Übersetzen von <code>Rte.c</code> die Abhängigkeiten über die Pfeilrichtungen auf. <code>Rte.c</code> bindet die anwendungsspezifischen Header sowie RTE-interne Header ein. Indirekt wird über <code>Rte_Type.h</code> und <code>Rte_Main.h</code> stets die übergeordnete standardisierte Schnittstellendefinition <code>Rte.h</code> referenziert, während Konfigurationsparameter aus <code>Rte_Cfg.h</code> über <code>Rte_Hook.h</code> bereitgestellt werden. Es findet kein dynamischer Laufzeit-Nachrichtenaustausch statt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt beispielhaften Charakter („Example of header file use by the generated RTE“) für Codegeneratoren und Integratoren. Die genaue Struktur der Inklusionen in <code>Rte.c</code> ist ein Implementierungsdetail des RTE-Generators. Wesentlich ist die Trennung zwischen generierten Artefakten („Generated“, grau) und standardisierten Header-Dateien („Standardized“, weiß), um zirkuläre Abhängigkeiten zu vermeiden und konsistente Typdefinitionen sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e1d8d4ff071a0348", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dateiorganisationsdiagramm (Include-Hierarchie / Komponentenabhängigkeitsdiagramm) der AUTOSAR Classic Platform RTE. Dargestellt ist die beispielhafte Inklusionsbeziehung zwischen dem generierten RTE-Quellcode (<code>Rte.c</code>), den zugehörigen generierten Header-Dateien sowie den standardisierten Schnittstellen-Headern der RTE-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dateien und Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code>: Generiertes C-Implementierungsmodul des RTE („Generated RTE“, grau).\n</li><li><code>Application Header File</code>: Generierte komponenten-spezifische Header-Dateien (grau, gestapelt dargestellt, Kardinalität <code>*</code>).\n</li><li><code>Rte_Type.h</code>: Generierter Typdefinitions-Header der RTE (grau).\n</li><li><code>Rte_Main.h</code>: Generierter Header für Lifecycle- und Scheduling-Funktionen (grau).\n</li><li><code>Rte_Hook.h</code>: Generierter Header für RTE-Hook-Routinen (grau).\n</li><li><code>Rte.h</code>: Standardisierter RTE-Basis-Header (weiß / „Standardized“).\n</li><li><code>Rte_Cfg.h</code>: Standardisierter Konfigurations-Header (weiß / „Standardized“).\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code> inkludiert <code>Rte_Hook.h</code> (Multiplizität <code>1</code>), <code>Application Header File</code> (Multiplizität <code>*</code>), <code>Rte_Type.h</code> (Multiplizität <code>1</code>) und <code>Rte_Main.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Hook.h</code> inkludiert <code>Rte_Cfg.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Application Header File</code> inkludiert <code>Rte_Type.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Type.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Main.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Include- und Kompilierzeit-Ablauf: Der C-Präprozessor löst beim Übersetzen von <code>Rte.c</code> die Abhängigkeiten über die Pfeilrichtungen auf. <code>Rte.c</code> bindet die anwendungsspezifischen Header sowie RTE-interne Header ein. Indirekt wird über <code>Rte_Type.h</code> und <code>Rte_Main.h</code> stets die übergeordnete standardisierte Schnittstellendefinition <code>Rte.h</code> referenziert, während Konfigurationsparameter aus <code>Rte_Cfg.h</code> über <code>Rte_Hook.h</code> bereitgestellt werden. Es findet kein dynamischer Laufzeit-Nachrichtenaustausch statt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt beispielhaften Charakter („Example of header file use by the generated RTE“) für Codegeneratoren und Integratoren. Die genaue Struktur der Inklusionen in <code>Rte.c</code> ist ein Implementierungsdetail des RTE-Generators. Wesentlich ist die Trennung zwischen generierten Artefakten („Generated“, grau) und standardisierten Header-Dateien („Standardized“, weiß), um zirkuläre Abhängigkeiten zu vermeiden und konsistente Typdefinitionen sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6df6f902812a7fb1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dateiorganisationsdiagramm (Include-Hierarchie / Komponentenabhängigkeitsdiagramm) der AUTOSAR Classic Platform RTE zur Verdeutlichung der Header-Include-Struktur bei Typentkopplung und Datenhandle-Typen. Dargestellt ist das Zusammenspiel zwischen dem C-Modul <code>Rte.c</code>, den generierten Applikations- und RTE-Headern sowie dem standardisierten Header <code>Rte.h</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dateien und Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code>: Generiertes RTE-Implementierungsmodul („Generated RTE“, grau).\n</li><li><code>Application Header File</code>: Generierte komponentenbezogene Header-Dateien (grau, gestapelt, Kardinalität <code>*</code>).\n</li><li><code>Application Types Header File</code>: Generierte komponentenbezogene Typ-Header-Dateien (grau, gestapelt, Kardinalität <code>1</code> je Komponente).\n</li><li><code>Rte_DataHandleType.h</code>: Generierter Header für Daten-Handle-Typdefinitionen (grau).\n</li><li><code>Rte_Type.h</code>: Generierter RTE-Typdefinitionen-Header (grau).\n</li><li><code>Rte_Cfg.h</code>: Generierter RTE-Konfigurations-Header (grau / „Generated“).\n</li><li><code>Rte_Hook.h</code>: Generierter Hook-Header (grau).\n</li><li><code>Rte_Main.h</code>: Generierter Lifecycle- und Scheduling-Header (grau).\n</li><li><code>Rte.h</code>: Standardisierter RTE-Basis-Header (weiß / „Standardized“).\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten</strong>:\n<ul class=\"fig-list\"><li><code>Rte.c</code> inkludiert <code>Rte_Hook.h</code> (Multiplizität <code>1</code>), <code>Application Header File</code> (Multiplizität <code>*</code>), <code>Rte_Type.h</code> (Multiplizität <code>1</code>) und <code>Rte_Main.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Hook.h</code> inkludiert <code>Rte_Cfg.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Application Header File</code> inkludiert <code>Rte_DataHandleType.h</code> (Multiplizität <code>1</code>) sowie <code>Application Types Header File</code> (Multiplizität <code>1</code>).\n</li><li><code>Application Types Header File</code> inkludiert <code>Rte_Type.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Type.h</code> inkludiert <code>Rte_Cfg.h</code> (Multiplizität <code>1</code>) sowie <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li><li><code>Rte_Main.h</code> inkludiert <code>Rte.h</code> (Multiplizität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Kompilierzeit-Inklusionskette: <code>Rte.c</code> bindet die Kern-Header und Applikations-Header ein. Die Typinklusion für Software-Komponenten ist zweistufig gegliedert: <code>Application Header File</code> bindet <code>Application Types Header File</code> und <code>Rte_DataHandleType.h</code> ein; erst <code>Application Types Header File</code> inkludiert <code>Rte_Type.h</code>. <code>Rte_Type.h</code> wiederum bindet sowohl den Konfigurations-Header <code>Rte_Cfg.h</code> als auch den Basis-Header <code>Rte.h</code> ein. Es liegt kein Laufzeitablauf vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzbeispiel für RTE-Generatoren. Wesentliche normative Aspekte für Entwickler und Generator-Implementierer sind:</p>\n<ul class=\"fig-list\"><li><code>Rte_Cfg.h</code> wird als generierte Datei geführt und nicht nur von <code>Rte_Hook.h</code>, sondern auch von <code>Rte_Type.h</code> inkludiert.\n</li><li>Entkopplung von Typdefinitionen über separate <code>Application Types Header Files</code> zur Minimierung von Header-Abhängigkeiten.\n</li><li>Einführung von <code>Rte_DataHandleType.h</code> zur Typisierung von Daten-Handles innerhalb der Komponenten-Header.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3eaf825f241c5298", "to": "FIG-719a7e57d62637c1", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-719a7e57d62637c1", "to": "FIG-e1d8d4ff071a0348", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e1d8d4ff071a0348", "to": "FIG-6df6f902812a7fb1", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neue generierte Header-Dateien <code>Application Types Header File</code> (Kardinalität <code>1</code>) und <code>Rte_DataHandleType.h</code> (Kardinalität <code>1</code>) als Abhängigkeiten von <code>Application Header File</code> hinzugefügt.\n</li><li><code>Rte_Type.h</code> bindet neu <code>Rte_Cfg.h</code> (Kardinalität <code>1</code>) ein; <code>Rte_Cfg.h</code> ist neu als generiert („Generated“, grau hinterlegt) statt standardisiert („Standardized“, weiß) deklariert.\n</li><li><code>Application Header File</code> bindet nun <code>Application Types Header File</code> ein, welches wiederum <code>Rte_Type.h</code> inkludiert (zuvor direkte Inklusion von <code>Rte_Type.h</code> durch <code>Application Header File</code>).\n</li><li>Anordnung in der Legende („Key“) vertauscht („Standardized“ oben, „Generated“ unten).\n</li></ul>"}]};
